using System.Text.Json;

namespace DeepDelver;

public enum HeroClass { Warden, Arcanist, Ranger }
public enum ItemKind { Sword, Bow, Staff, Leather, Mail, Ration, Potion, Scroll, Wand, Star }
public sealed class Item { public int Id { get; set; } public ItemKind Kind { get; set; } public string Name { get; set; } = ""; public int Power { get; set; } public int Charges { get; set; } }
public sealed class Monster { public int Id { get; set; } public string Kind { get; set; } = ""; public int X { get; set; } public int Y { get; set; } public int Hp { get; set; } public int MaxHp { get; set; } public int Attack { get; set; } public int Defense { get; set; } public int Xp { get; set; } public string Ai { get; set; } = "chase"; }
public sealed class Floor { public int Depth { get; set; } public char[][] Tiles { get; set; } = []; public bool[][] Seen { get; set; } = []; public Dictionary<string,List<Item>> Items { get; set; } = []; public List<Monster> Monsters { get; set; } = []; public int UpX { get; set; } public int UpY { get; set; } public int DownX { get; set; } public int DownY { get; set; } }
public sealed class Hero { public HeroClass Class { get; set; } public int X { get; set; } public int Y { get; set; } public int Hp { get; set; } public int MaxHp { get; set; } public int Mana { get; set; } public int MaxMana { get; set; } public int Level { get; set; }=1; public int Xp { get; set; } public int NextXp { get; set; }=18; public int Hunger { get; set; }=900; public int Poison { get; set; } public List<Item> Inventory { get; set; }=[]; public int Weapon { get; set; } public int Armor { get; set; } public bool HasStar { get; set; } }
public sealed class State { public int Version { get; set; }=1; public uint Seed { get; set; } public uint Rng { get; set; } public int Turn { get; set; } public int Depth { get; set; } public Dictionary<int,Floor> Floors { get; set; }=[]; public Hero Hero { get; set; }=new(); public List<string> Messages { get; set; }=[]; public string Mode { get; set; }="playing"; }

public sealed class Game {
    public State State { get; private set; } = new(); private int nextId=1; const int W=56,H=28;
    public Game(uint seed, HeroClass heroClass) { seed=seed==0?1:seed; var (hp,mp)=heroClass switch {HeroClass.Warden=>(28,4),HeroClass.Arcanist=>(18,14),_=>(22,7)}; State=new State{Seed=seed,Rng=seed,Hero=new Hero{Class=heroClass,Hp=hp,MaxHp=hp,Mana=mp,MaxMana=mp}}; var floor=MakeFloor(0);State.Floors[0]=floor;State.Hero.X=floor.UpX;State.Hero.Y=floor.UpY; Starter(heroClass); Say($"Welcome to Deep Delver. Seed {seed}."); Reveal(); }
    public static Game Load(string text) { var state=JsonSerializer.Deserialize<State>(text) ?? throw new InvalidDataException("Invalid save"); if(state.Version!=1)throw new InvalidDataException("Unsupported save"); var game=new Game(1,HeroClass.Warden){State=state}; var ids=state.Floors.Values.SelectMany(f=>f.Monsters.Select(m=>m.Id).Concat(f.Items.Values.SelectMany(x=>x).Select(i=>i.Id))).Concat(state.Hero.Inventory.Select(i=>i.Id)); game.nextId=ids.DefaultIfEmpty(0).Max()+1; return game; }
    public string Save() => JsonSerializer.Serialize(State);
    int Rand(int max) { uint x=State.Rng; x^=x<<13;x^=x>>17;x^=x<<5;State.Rng=x;return (int)(x%(uint)max); }
    void Say(string text){State.Messages.Insert(0,text);if(State.Messages.Count>80)State.Messages.RemoveRange(80,State.Messages.Count-80);} Floor F=>State.Floors[State.Depth]; static string Key(int x,int y)=>$"{x},{y}";
    void Give(ItemKind k,string n,int p,int charges=0){State.Hero.Inventory.Add(new Item{Id=nextId++,Kind=k,Name=n,Power=p,Charges=charges});}
    void Starter(HeroClass c){if(c==HeroClass.Warden){Give(ItemKind.Sword,"iron sword",4);Give(ItemKind.Mail,"ring mail",2);Give(ItemKind.Ration,"travel ration",0);State.Hero.Weapon=1;State.Hero.Armor=2;}else if(c==HeroClass.Arcanist){Give(ItemKind.Staff,"oak staff",2);Give(ItemKind.Scroll,"sealed scroll",6);Give(ItemKind.Potion,"murky potion",7);State.Hero.Weapon=1;}else{Give(ItemKind.Bow,"short bow",3);Give(ItemKind.Leather,"leather coat",1);Give(ItemKind.Ration,"travel ration",0);Give(ItemKind.Wand,"ivory wand",5,4);State.Hero.Weapon=1;State.Hero.Armor=2;}}
    char Tile(Floor f,int x,int y)=>x<0||y<0||x>=W||y>=H?'#':f.Tiles[y][x]; bool Pass(Floor f,int x,int y)=>"./<>^".Contains(Tile(f,x,y));
    Floor MakeFloor(int depth){var t=Enumerable.Range(0,H).Select(_=>Enumerable.Repeat('#',W).ToArray()).ToArray();var seen=Enumerable.Range(0,H).Select(_=>new bool[W]).ToArray();var rooms=new List<(int x,int y,int w,int h)>();for(int n=0;n<16;n++){int rw=5+Rand(8),rh=4+Rand(5),rx=1+Rand(W-rw-2),ry=1+Rand(H-rh-2);if(rooms.Any(r=>rx<r.x+r.w+2&&rx+rw+2>r.x&&ry<r.y+r.h+2&&ry+rh+2>r.y))continue;rooms.Add((rx,ry,rw,rh));for(int y=ry;y<ry+rh;y++)for(int x=rx;x<rx+rw;x++)t[y][x]='.';}if(rooms.Count<2)return MakeFloor(depth);(int x,int y) C((int x,int y,int w,int h)r)=>(r.x+r.w/2,r.y+r.h/2);for(int i=1;i<rooms.Count;i++){var a=C(rooms[i-1]);var b=C(rooms[i]);for(int x=Math.Min(a.x,b.x);x<=Math.Max(a.x,b.x);x++)t[a.y][x]='.';for(int y=Math.Min(a.y,b.y);y<=Math.Max(a.y,b.y);y++)t[y][b.x]='.';}var up=C(rooms[0]);var down=C(rooms[^1]);t[up.y][up.x]='<';t[down.y][down.x]='>';foreach(var r in rooms.Skip(1).Take(rooms.Count-2))if(Rand(3)==0)t[r.y][r.y%2==0?r.x:r.x+r.w-1]='+';var f=new Floor{Depth=depth,Tiles=t,Seen=seen,UpX=up.x,UpY=up.y,DownX=down.x,DownY=down.y};foreach(var r in rooms){for(int z=0;z<1+Rand(2);z++)SpawnMonster(f,depth,r);if(Rand(2)==0)SpawnItem(f,depth,r);}if(depth==9){f.Monsters.Clear();f.Monsters.Add(new Monster{Id=nextId++,Kind="guardian",X=down.x-1,Y=down.y,Hp=60,MaxHp=60,Attack=10,Defense=4,Xp=80,Ai="guard"});Add(f,down.x,down.y,new Item{Id=nextId++,Kind=ItemKind.Star,Name="Star of the Deep"});}return f;}
    (int x,int y) Empty(Floor f,(int x,int y,int w,int h)r){for(int i=0;i<80;i++){var x=r.x+Rand(r.w);var y=r.y+Rand(r.h);if(Pass(f,x,y)&&!f.Monsters.Any(m=>m.X==x&&m.Y==y)&&!(x==f.UpX&&y==f.UpY))return(x,y);}return(r.x,r.y);}
    void SpawnMonster(Floor f,int d,(int x,int y,int w,int h)r){var options=d<2?new[]{"rat","goblin"}:d<5?new[]{"goblin","archer","wraith"}:new[]{"archer","wraith"};var k=options[Rand(options.Length)];var data=k switch {"rat"=>(5,2,0,"wander"),"goblin"=>(8,3,1,"chase"),"archer"=>(7,3,0,"ranged"),_=>(13,5,2,"chase")};var p=Empty(f,r);f.Monsters.Add(new Monster{Id=nextId++,Kind=k,X=p.x,Y=p.y,Hp=data.Item1+d/2,MaxHp=data.Item1+d/2,Attack=data.Item2+d/3,Defense=data.Item3,Xp=data.Item1+d,Ai=data.Item4});}
    void SpawnItem(Floor f,int d,(int x,int y,int w,int h)r){var kinds=new[]{ItemKind.Ration,ItemKind.Potion,ItemKind.Scroll,ItemKind.Wand,ItemKind.Sword,ItemKind.Leather};var k=kinds[Rand(kinds.Length)];var names=new Dictionary<ItemKind,string>{{ItemKind.Ration,"travel ration"},{ItemKind.Potion,"murky potion"},{ItemKind.Scroll,"sealed scroll"},{ItemKind.Wand,"ivory wand"},{ItemKind.Sword,"rusted sword"},{ItemKind.Leather,"leather coat"}};var p=Empty(f,r);Add(f,p.x,p.y,new Item{Id=nextId++,Kind=k,Name=names[k],Power=k==ItemKind.Potion?7:k==ItemKind.Scroll?6:k==ItemKind.Wand?5:k==ItemKind.Sword?3:k==ItemKind.Leather?1:0,Charges=k==ItemKind.Wand?2+Rand(4):0});}
    void Add(Floor f,int x,int y,Item item){var key=Key(x,y);if(!f.Items.ContainsKey(key))f.Items[key]=[];f.Items[key].Add(item);} bool Visible(int x,int y){var h=State.Hero;var dx=x-h.X;var dy=y-h.Y;if(dx*dx+dy*dy>81)return false;var n=Math.Max(Math.Abs(dx),Math.Abs(dy));for(int i=1;i<n;i++)if(Tile(F,h.X+(int)Math.Round(dx*(double)i/n),h.Y+(int)Math.Round(dy*(double)i/n))=='#')return false;return true;} void Reveal(){for(int y=0;y<H;y++)for(int x=0;x<W;x++)if(Visible(x,y))F.Seen[y][x]=true;}
    public char Glyph(int x,int y){var h=State.Hero;if(h.X==x&&h.Y==y)return '@';if(!F.Seen[y][x])return ' ';if(Visible(x,y)){var m=F.Monsters.FirstOrDefault(q=>q.X==x&&q.Y==y);if(m!=null)return m.Kind switch{"rat"=>'r',"goblin"=>'g',"archer"=>'a',"wraith"=>'W',_=>'G'};if(F.Items.TryGetValue(Key(x,y),out var pile)&&pile.Count>0)return pile[0].Kind==ItemKind.Star?'*':pile[0].Kind==ItemKind.Ration?'%':'!';}return F.Tiles[y][x];}
    public void Act(string command,int itemId=0){if(State.Mode!="playing")return;var h=State.Hero;var spent=false;var move=command.ToLowerInvariant() switch{"up"=>(0,-1),"down"=>(0,1),"left"=>(-1,0),"right"=>(1,0),"nw"=>(-1,-1),"ne"=>(1,-1),"sw"=>(-1,1),"se"=>(1,1),_=>(0,0)};if(move!=(0,0)){var x=h.X+move.Item1;var y=h.Y+move.Item2;var m=F.Monsters.FirstOrDefault(q=>q.X==x&&q.Y==y);if(m!=null){Hit(m);spent=true;}else if(Tile(F,x,y)=='+'){F.Tiles[y][x]='/';Say("You open a door.");spent=true;}else if(Pass(F,x,y)){h.X=x;h.Y=y;Trigger();spent=true;}else Say("Blocked.");}else if(command=="rest"){h.Hp=Math.Min(h.MaxHp,h.Hp+1);h.Mana=Math.Min(h.MaxMana,h.Mana+1);Say("You wait.");spent=true;}else if(command=="get"){if(F.Items.TryGetValue(Key(h.X,h.Y),out var pile)&&pile.Count>0){var i=pile[0];pile.RemoveAt(0);h.Inventory.Add(i);h.HasStar|=i.Kind==ItemKind.Star;Say($"You pick up {i.Name}.");spent=true;}else Say("Nothing here.");}else if(command=="search"){var found=false;foreach(var(dy,dx) in new[]{(0,1),(0,-1),(1,0),(-1,0)}){var x=h.X+dx;var y=h.Y+dy;if(Tile(F,x,y)=='#'&&Rand(5)==0){F.Tiles[y][x]='/';found=true;break;}}Say(found?"A secret door yields.":"You find nothing.");spent=true;}else if(command=="descend"||command=="ascend"){var wanted=command=="descend"?'>':'<';if(Tile(F,h.X,h.Y)!=wanted)Say("No stairs here.");else Travel(command=="descend"?1:-1);return;}else {var i=h.Inventory.FirstOrDefault(q=>q.Id==itemId);if(i==null){Say("That item is gone.");return;}if(command=="equip"&&(i.Kind is ItemKind.Sword or ItemKind.Bow or ItemKind.Staff or ItemKind.Leather or ItemKind.Mail)){if(i.Kind is ItemKind.Sword or ItemKind.Bow or ItemKind.Staff)h.Weapon=i.Id;else h.Armor=i.Id;Say($"Equipped {i.Name}.");spent=true;}else if(command=="use")spent=Use(i);else if(command=="fire")spent=Fire(i);else if(command=="drop"){h.Inventory.Remove(i);Add(F,h.X,h.Y,i);Say($"Dropped {i.Name}.");spent=true;}}if(spent)EndTurn();}
    Item? Weapon()=>State.Hero.Inventory.FirstOrDefault(i=>i.Id==State.Hero.Weapon); Item? Armor()=>State.Hero.Inventory.FirstOrDefault(i=>i.Id==State.Hero.Armor);
    void Hit(Monster m){var n=Math.Max(1,2+(Weapon()?.Power??0)-m.Defense+Rand(4));m.Hp-=n;Say($"You hit {m.Kind} for {n}.");if(m.Hp<=0){F.Monsters.Remove(m);Gain(m.Xp);Say($"The {m.Kind} falls.");}}
    bool Use(Item i){var h=State.Hero;if(i.Kind==ItemKind.Ration){h.Hunger=Math.Min(1000,h.Hunger+360);h.Inventory.Remove(i);Say("You eat the ration.");return true;}if(i.Kind==ItemKind.Potion){h.Hp=Math.Min(h.MaxHp,h.Hp+10);h.Poison=0;i.Name="potion of renewal";h.Inventory.Remove(i);Say("You identify a potion of renewal.");return true;}if(i.Kind==ItemKind.Scroll)return Fire(i);Say("Nothing happens.");return false;}
    bool Fire(Item i){var h=State.Hero;if(i.Kind is not(ItemKind.Bow or ItemKind.Staff or ItemKind.Wand or ItemKind.Scroll)){Say("That cannot be fired.");return false;}if(i.Kind==ItemKind.Staff&&h.Mana<3){Say("Not enough mana.");return false;}if(i.Kind==ItemKind.Wand&&i.Charges<1){Say("The wand is dry.");return false;}var m=F.Monsters.Where(q=>Visible(q.X,q.Y)).OrderBy(q=>(q.X-h.X)*(q.X-h.X)+(q.Y-h.Y)*(q.Y-h.Y)).FirstOrDefault();if(m==null){Say("No target in sight.");return false;}var damage=i.Kind==ItemKind.Scroll?8:i.Kind==ItemKind.Wand?7:i.Kind==ItemKind.Staff?6:4+Rand(3);if(i.Kind==ItemKind.Staff)h.Mana-=3;if(i.Kind==ItemKind.Wand)i.Charges--;if(i.Kind==ItemKind.Scroll)h.Inventory.Remove(i);m.Hp-=damage;Say($"A bolt strikes {m.Kind} for {damage}.");if(m.Hp<=0){F.Monsters.Remove(m);Gain(m.Xp);}return true;}
    void Trigger(){var h=State.Hero;if(Tile(F,h.X,h.Y)=='^'){h.Hp-=4;F.Tiles[h.Y][h.X]='.';Say("A spike trap bites you!");}else if(Rand(45)==0)F.Tiles[h.Y][h.X]='^';}void Gain(int xp){var h=State.Hero;h.Xp+=xp;while(h.Xp>=h.NextXp){h.Xp-=h.NextXp;h.NextXp=(int)(h.NextXp*1.55);h.Level++;h.MaxHp+=5;h.Hp=h.MaxHp;h.MaxMana+=2;h.Mana=h.MaxMana;Say($"You reach level {h.Level}!");}}
    void EndTurn(){var h=State.Hero;if(--h.Hunger<1){h.Hp--;Say("You are starving!");}if(h.Poison>0)h.Hp-=h.Poison;Monsters();State.Turn++;Reveal();if(h.Hp<=0){State.Mode="dead";Say("You have died in the depths.");}}
    void Monsters(){var h=State.Hero;foreach(var m in F.Monsters.ToList()){var dx=h.X-m.X;var dy=h.Y-m.Y;var d=Math.Max(Math.Abs(dx),Math.Abs(dy));if(d==1){var hit=Math.Max(1,m.Attack-(Armor()?.Power??0)+Rand(3));h.Hp-=hit;Say($"{m.Kind} hits you for {hit}.");if(m.Kind=="wraith"&&Rand(5)==0)h.Poison=1;continue;}if(m.Ai=="ranged"&&d<7&&Visible(m.X,m.Y)){h.Hp-=m.Attack;Say($"{m.Kind} shoots you for {m.Attack}.");continue;}if(d<9&&(m.Ai!="wander"||Rand(2)==0)){var sx=Math.Sign(dx);var sy=Math.Sign(dy);var nx=m.X+(Math.Abs(dx)>Math.Abs(dy)?sx:0);var ny=m.Y+(Math.Abs(dx)>Math.Abs(dy)?0:sy);if(Pass(F,nx,ny)&&!(nx==h.X&&ny==h.Y)&&!F.Monsters.Any(q=>q!=m&&q.X==nx&&q.Y==ny)){m.X=nx;m.Y=ny;}}}}
    void Travel(int delta){var next=State.Depth+delta;var h=State.Hero;if(next<0){if(h.HasStar){State.Mode="won";Say("You bear the Star into daylight. Victory!");}else Say("You cannot leave without the Star.");return;}if(next>9){Say("The guardian chamber is the bottom.");return;}if(!State.Floors.ContainsKey(next))State.Floors[next]=MakeFloor(next);State.Depth=next;var f=F;h.X=delta>0?f.UpX:f.DownX;h.Y=delta>0?f.UpY:f.DownY;Say($"You enter depth {next+1}.");Reveal();}
}
